function [a] = rotor_axes(m, d)
%ROTOR_AXES  The rotors' spin axes (body) at the gimbal angles d.
%   m: RotorGeometry (passed rec)
%   d: real[1][DYN_NG] (passed a plain number)
%   returns a: real[1][3][DYN_NR] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = zeros(8, 3);
    a = m.a0;
    for ir = (0):((m.nr) - 1)
        jg = m.gi((ir) + 1);
        if (jg > 0)
            dj = d(((jg - 1)) + 1);
            k = ((0):((3) - 1)).';
            a((ir) + 1, (k) + 1) = (((cos(dj) .* (m.a0((ir) + 1, (k) + 1)).') + (sin(dj) .* (m.t0((ir) + 1, (k) + 1)).'))).';
        end
    end
end
